import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int D = nextInt(), U = nextInt();
        // Difference array: number of usage=1 intervals covering each day.
        int[] diff = new int[D + 2];
        for (int i = 0; i < U; i++) {
            int l = nextInt(), r = nextInt(), v = nextInt();
            if (v != 0) {
                diff[l]++;
                diff[r + 1]--;
            }
        }
        int O = nextInt();
        // Overrides do not overlap, so writing them directly costs their total length.
        byte[] over = new byte[D + 1];
        Arrays.fill(over, (byte) -1);
        for (int i = 0; i < O; i++) {
            int l = nextInt(), r = nextInt(), v = nextInt();
            for (int d = l; d <= r; d++) over[d] = (byte) v;
        }
        char[] out = new char[D];
        int cur = 0;
        for (int d = 1; d <= D; d++) {
            cur += diff[d];
            out[d - 1] = over[d] < 0 ? (cur > 0 ? '1' : '0') : (char) ('0' + over[d]);
        }
        System.out.println(new String(out));
    }
}

package main

import (
	"bufio"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	D, U := nextInt(), nextInt()
	// Difference array: number of usage=1 intervals covering each day.
	diff := make([]int, D+2)
	for i := 0; i < U; i++ {
		l, r, v := nextInt(), nextInt(), nextInt()
		if v != 0 {
			diff[l]++
			diff[r+1]--
		}
	}
	O := nextInt()
	// Overrides do not overlap, so writing them directly costs their total length.
	over := make([]int8, D+1)
	for i := range over {
		over[i] = -1
	}
	for i := 0; i < O; i++ {
		l, r, v := nextInt(), nextInt(), nextInt()
		for d := l; d <= r; d++ {
			over[d] = int8(v)
		}
	}
	out := make([]byte, D)
	cur := 0
	for d := 1; d <= D; d++ {
		cur += diff[d]
		switch {
		case over[d] >= 0:
			out[d-1] = byte('0' + over[d])
		case cur > 0:
			out[d-1] = '1'
		default:
			out[d-1] = '0'
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.Write(out)
	w.WriteByte('\n')
}
